// `open-color@1.9`'s shape: the file `"types"` points at is not a module at
// all. It is a SCRIPT whose entire content is a global `declare module` block
// naming the package — right down to the single quotes.
declare module 'swatch' {
  type Color = string;
  interface Swatch {
    red: Color[];
    blue: Color[];
  }
  const swatch: Swatch;
  export default swatch;
}
